-- Adds light Markdown (bold the final answer) to the 40 Mathematics
-- question answers (migrations/0021), now that the frontend renders
-- Markdown in answer text (components/layout/Markdown.tsx) instead of
-- showing it as plain strings. Scoped to this one set deliberately: it's
-- the only curriculum content authored in this session with a clean,
-- uniform "worked solution -> one final answer" shape safe to bold
-- mechanically by hand; the rest of the (much larger, pre-existing)
-- curriculum needs a human-reviewed pass before any bulk reformatting,
-- not an automated one.

UPDATE questions SET a = 'Using the formula for the sum of the first n natural numbers, n(n+1)/2: for n = 50, the sum is 50 × 51 / 2 = **1275**.' WHERE id = 'math-q01';
UPDATE questions SET a = '36 = 2² × 3² and 60 = 2² × 3 × 5. The HCF takes the lowest power of each common prime factor: 2² × 3 = **12**.' WHERE id = 'math-q02';
UPDATE questions SET a = '12 = 2² × 3 and 18 = 2 × 3². The LCM takes the highest power of each prime factor present: 2² × 3² = **36**.' WHERE id = 'math-q03';
UPDATE questions SET a = '2^10 = 1024. Dividing 1024 by 7 gives 7 × 146 = 1022, leaving a remainder of 1024 − 1022 = **2**.' WHERE id = 'math-q04';
UPDATE questions SET a = 'The number can be written as 15k + 7 for some integer k. Since 15k is always divisible by 5, the remainder when dividing by 5 comes only from 7 — and 7 divided by 5 leaves a remainder of **2**.' WHERE id = 'math-q05';
UPDATE questions SET a = 'The required number is (LCM of 12, 15, and 20) + 5. LCM(12, 15, 20) = 60, so the smallest such number is 60 + 5 = **65**.' WHERE id = 'math-q06';
UPDATE questions SET a = 'Computing each term: 0.75 × 0.75 = 0.5625, 0.75 × 0.25 = 0.1875, and 0.25 × 0.25 = 0.0625. Their sum is 0.5625 + 0.1875 + 0.0625 = **0.8125** (equivalently 13/16).' WHERE id = 'math-q07';
UPDATE questions SET a = '0.0081 = 81/10000, and the square root of a fraction is the square root of the numerator over the square root of the denominator: √81/√10000 = 9/100 = **0.09**.' WHERE id = 'math-q08';
UPDATE questions SET a = 'Starting from 100, a 20% increase gives 100 × 1.2 = 120, and then a 20% decrease gives 120 × 0.8 = 96. The net change is 96 − 100 = −4, i.e., a net decrease of **4%**.' WHERE id = 'math-q09';
UPDATE questions SET a = 'Starting from 100, increasing by 25% gives 100 × 1.25 = 125, and then decreasing by 20% gives 125 × 0.8 = 100. So the final price equals **100%** of the original — no net change.' WHERE id = 'math-q10';
UPDATE questions SET a = 'Let the original cost price be ₹x, so the original selling price is 1.2x. The new cost price would be 0.9x, and the new selling price would be 1.2x + 30. A 40% gain on the new cost price means the new selling price equals 1.4 × 0.9x = 1.26x. Setting these equal: 1.26x = 1.2x + 30, so 0.06x = 30, giving x = **₹500**.' WHERE id = 'math-q11';
UPDATE questions SET a = 'The amount after 2 years is 15,000 × (1.2)² = 15,000 × 1.44 = ₹21,600. The compound interest is 21,600 − 15,000 = **₹6,600**.' WHERE id = 'math-q12';
UPDATE questions SET a = 'The amount for the 3rd year equals the amount for the 2nd year multiplied by (1 + rate/100), since compound interest grows the existing amount by one more year''s interest. So 5,717.25 / 5,445 = 1.05, meaning the rate of interest is **5% per annum**.' WHERE id = 'math-q13';
UPDATE questions SET a = 'Let the cost price per article be ₹1. Then the selling price of 20 articles (20 × SP) equals the cost price of 25 articles (25 × 1 = 25), so SP = 25/20 = 1.25 per article. Since the cost price per article is ₹1, the profit percentage is (1.25 − 1) × 100 = **25%**.' WHERE id = 'math-q14';
UPDATE questions SET a = 'The cost price is ₹1,200, regardless of what it was actually sold for. To gain 10% instead, the selling price should be 1,200 × 1.1 = **₹1,320**.' WHERE id = 'math-q15';
UPDATE questions SET a = 'Applying both discounts to 100: 100 × 0.9 × 0.8 = 72. This means the final price is 72% of the original, which corresponds to a single equivalent discount of 100 − 72 = **28%**.' WHERE id = 'math-q16';
UPDATE questions SET a = 'Let the numbers be 4x and 5x. After subtracting 6 from each: (4x − 6)/(5x − 6) = 3/4. Cross-multiplying: 4(4x − 6) = 3(5x − 6), so 16x − 24 = 15x − 18, giving x = 6. The numbers are **24 and 30**.' WHERE id = 'math-q17';
UPDATE questions SET a = 'The sum of all 11 numbers is 11 × 48 = 528. The sum of the first 6 is 6 × 45 = 270, and the sum of the last 6 is 6 × 52 = 312. Since the 6th number is counted in both groups, adding these two sums double-counts it: 270 + 312 = 582 = 528 + (6th number), so the 6th number is 582 − 528 = **54**.' WHERE id = 'math-q18';
UPDATE questions SET a = 'Using the rule of alligation, the ratio of the cheaper to the dearer quantity equals (dearer price − mean price) : (mean price − cheaper price) = (30 − 24) : (24 − 20) = 6 : 4 = 3 : 2. So the ₹20/kg rice and ₹30/kg rice should be mixed in the ratio **3:2**.' WHERE id = 'math-q19';
UPDATE questions SET a = 'Let A''s age 10 years ago be x and B''s age be 2x. Today their ages are (x + 10) and (2x + 10), and these are in the ratio 3:5: (x + 10)/(2x + 10) = 3/5. Cross-multiplying: 5(x + 10) = 3(2x + 10), so 5x + 50 = 6x + 30, giving x = 20. A''s present age is x + 10 = **30 years**.' WHERE id = 'math-q20';
UPDATE questions SET a = 'The mixture has 40 × 0.1 = 4 litres of water and 36 litres of milk. If w litres of water are added, the new total volume is (40 + w) litres and the new water content is (4 + w) litres. Setting (4 + w)/(40 + w) = 0.2: 4 + w = 8 + 0.2w, so 0.8w = 4, giving w = **5 litres**.' WHERE id = 'math-q21';
UPDATE questions SET a = 'The total weight of all 25 students is 25 × 52 = 1,300 kg. After one student leaves, the total weight of the remaining 24 students is 24 × 51.5 = 1,236 kg. The weight of the student who left is 1,300 − 1,236 = **64 kg**.' WHERE id = 'math-q22';
UPDATE questions SET a = 'The fraction of milk in Vessel A is 2/5 = 0.4, and in Vessel B it is 4/5 = 0.8. Using alligation to reach a target fraction of 0.5: the ratio of Vessel A to Vessel B is (0.8 − 0.5) : (0.5 − 0.4) = 0.3 : 0.1 = 3 : 1. So the vessels should be mixed in the ratio **3:1** (Vessel A to Vessel B).' WHERE id = 'math-q23';
UPDATE questions SET a = 'Let the number of coins be 5x, 6x, and 8x respectively. Their total value is 5x × 1 + 6x × 0.50 + 8x × 0.25 = 5x + 3x + 2x = 10x. Setting 10x = 210 gives x = 21, so the number of ₹0.50 coins is 6 × 21 = **126**.' WHERE id = 'math-q24';
UPDATE questions SET a = 'The original speed is 420/6 = 70 km/h. Increasing it by 10 km/h gives a new speed of 80 km/h. The new time taken is 420/80 = 5.25 hours, i.e., **5 hours and 15 minutes**.' WHERE id = 'math-q25';
UPDATE questions SET a = 'Since the trains move in opposite directions, their relative speed is 54 + 36 = 90 km/h, which converts to 90 × 5/18 = 25 m/s. The total distance to be covered while crossing is the sum of their lengths, 120 + 180 = 300 m. Time taken = 300/25 = **12 seconds**.' WHERE id = 'math-q26';
UPDATE questions SET a = 'Upstream speed = 24/6 = 4 km/h, and downstream speed = 24/4 = 6 km/h. The boat''s speed in still water is the average of these: (4 + 6)/2 = **5 km/h**. The stream''s speed is half their difference: (6 − 4)/2 = **1 km/h**.' WHERE id = 'math-q27';
UPDATE questions SET a = 'A''s rate of work is 1/20 per day and B''s rate is 1/30 per day, so their combined rate is 1/20 + 1/30 = 3/60 + 2/60 = 5/60 = 1/12 per day. In 5 days together, they complete 5/12 of the work, leaving 7/12 remaining. B alone, at a rate of 1/30 per day, takes (7/12) ÷ (1/30) = (7/12) × 30 = **17.5 days** to finish the rest.' WHERE id = 'math-q28';
UPDATE questions SET a = 'Their combined one-day work is 1/10 + 1/15 + 1/30 = 3/30 + 2/30 + 1/30 = 6/30 = 1/5. So working together, they complete the entire work in **5 days**.' WHERE id = 'math-q29';
UPDATE questions SET a = 'The train''s speed is 72 km/h = 72 × 5/18 = 20 m/s. To fully cross the platform, the train must cover its own length plus the platform''s length: 300 + 500 = 800 m. The time taken is 800/20 = **40 seconds**.' WHERE id = 'math-q30';
UPDATE questions SET a = 'If the usual time is t, walking at 4/5 of the usual speed means the new time is t ÷ (4/5) = 1.25t, since time and speed are inversely proportional for a fixed distance. The extra time taken is 1.25t − t = 0.25t, and this equals 10 minutes, so t = **40 minutes**.' WHERE id = 'math-q31';
UPDATE questions SET a = 'The difference in speed, 60 − 48 = 12 km/h, represents distance lost to stoppages each hour. At the train''s actual moving speed of 60 km/h, covering this lost 12 km takes 12/60 hour = 0.2 hour = 12 minutes. So the train stops for **12 minutes per hour** on average.' WHERE id = 'math-q32';
UPDATE questions SET a = 'Squaring both sides of x + 1/x = 5 gives x² + 2 + 1/x² = 25, since (x + 1/x)² = x² + 2·x·(1/x) + 1/x² = x² + 2 + 1/x². So x² + 1/x² = 25 − 2 = **23**.' WHERE id = 'math-q33';
UPDATE questions SET a = 'Using the quadratic formula with a = 2, b = −7, c = 3: the discriminant is (−7)² − 4(2)(3) = 49 − 24 = 25, and √25 = 5. So x = (7 ± 5)/4, giving x = **3** or x = **0.5**.' WHERE id = 'math-q34';
UPDATE questions SET a = 'Using Heron''s formula, the semi-perimeter is s = (13 + 14 + 15)/2 = 21. The area is √(s(s−a)(s−b)(s−c)) = √(21 × 8 × 7 × 6) = √7056 = **84 cm²**.' WHERE id = 'math-q35';
UPDATE questions SET a = 'From the circumference formula, 2πr = 44, so r = 44 ÷ (2 × 22/7) = 44 × 7/44 = 7 cm. The area is πr² = 22/7 × 49 = **154 cm²**.' WHERE id = 'math-q36';
UPDATE questions SET a = 'The angles of a triangle always sum to 180°, so x + 2x + 3x = 6x = 180, giving x = **30**.' WHERE id = 'math-q37';
UPDATE questions SET a = 'The ladder, the wall, and the ground form a right triangle, so by the Pythagorean theorem the height is √(17² − 8²) = √(289 − 64) = √225 = **15 metres**.' WHERE id = 'math-q38';
UPDATE questions SET a = 'Looking for two numbers that multiply to 6 and add to −5 gives −2 and −3. So x² − 5x + 6 factorizes as **(x − 2)(x − 3)**.' WHERE id = 'math-q39';
UPDATE questions SET a = 'The side length is the cube root of 512, which is 8 cm, since 8³ = 512. The total surface area of a cube is 6 × (side)² = 6 × 64 = **384 cm²**.' WHERE id = 'math-q40';
